exercises.solution:
*** Test Cases ***
Scalar Variable Test
    ${system_name}    Set Variable    Navigation System
    Log    Checking system: ${system_name}
    Log Variable    ${system_name}
    ${status}    Set Variable    OPERATIONAL
    Log    System status: ${status}

*** Test Cases ***
Variable Naming Rules
    ${my_var}    Set Variable    Underscore style
    ${MyVar}     Set Variable    Camel case style
    ${MY_VAR}    Set Variable    All caps style
    ${my var}    Set Variable    Spaces allowed
    ${var123}    Set Variable    Numbers allowed
    Log    ${my_var}
    Log    ${MyVar}
    Log    ${MY_VAR}
    Log    ${my var}
    Log    ${var123}
    # Note: ${my-var} would be INVALID (hyphens not allowed)
    # Note: ${123var} would be INVALID (can't start with number)
    ${status}    Set Variable    online
    ${STATUS}    Set Variable    CRITICAL
    Log    Lowercase status: ${status}
    Log    Uppercase STATUS: ${STATUS}

*** Test Cases ***
List Variables Test
    @{damaged_systems}    Create List    Hull Sector 7    Navigation Array    Life Support Module 3    Communication Relay    Sensor Grid B
    Log Many    Damaged Systems:    @{damaged_systems}
    @{priority_repairs}    Create List    Life Support    Navigation    Hull Breach
    Log    Priority repairs: @{priority_repairs}

*** Test Cases ***
List Indexing Test
    @{systems}      Create List    Navigation    Power Core    Life Support    Weapons    Shields
    ${first}        Set Variable    ${systems}[0]
    Log             First system: ${first}
    ${last}         Set Variable    ${systems}[-1]
    Log             Last system: ${last}
    ${third}        Set Variable    ${systems}[2]
    Log             Third system: ${third}
    ${first_three}  Set Variable    ${systems}[0:3]
    Log             First three: ${first_three}
    ${last_two}     Set Variable    ${systems}[-2:]
    Log             Last two: ${last_two}

*** Test Cases ***
Dictionary Variables Test
    &{system_status}    Create Dictionary    Navigation=OPERATIONAL    Power=DEGRADED    LifeSupport=CRITICAL    Weapons=OFFLINE    Shields=OPERATIONAL
    Log Dictionary      ${system_status}
    &{crew_info}        Create Dictionary    captain=Commander Sarah Chen    engineer=Lt. Marcus Rivera    pilot=Ensign Alex Kim
    Log                 Crew: &{crew_info}

*** Test Cases ***
Dictionary Access Test
    &{systems}       Create Dictionary    Navigation=OPERATIONAL    Power=DEGRADED    LifeSupport=CRITICAL    Shields=OPERATIONAL
    ${nav_status}    Set Variable    ${systems}[Navigation]
    Log              Navigation: ${nav_status}
    ${power_status}  Set Variable    ${systems}[Power]
    Log              Power: ${power_status}
    ${ls_status}     Set Variable    ${systems}[LifeSupport]
    Log              Life Support: ${ls_status}
    &{crew}          Create Dictionary    captain=Sarah Chen    pilot=Alex Kim
    ${captain}       Set Variable    ${crew}[captain]
    Log              Captain: ${captain}
    ${pilot_name}    Get From Dictionary    ${crew}    pilot
    Log              Pilot: ${pilot_name}
